class _AddAdPageState extends State<AddAdPage>{final title=TextEditingController(),desc=TextEditingController(),price=TextEditingController(),brand=TextEditingController(),model=TextEditingController(),year=TextEditingController(),mileage=TextEditingController(),color=TextEditingController();final picker=ImagePicker();final images=<XFile>[];String category='کالای دیجیتال',subcategory='همه',city='تهران',transmission='دستی',fuel='بنزین',body='سالم';bool exchange=false,publishing=false;double? lat,lon;
 @override void dispose(){title.dispose();desc.dispose();price.dispose();brand.dispose();model.dispose();year.dispose();mileage.dispose();color.dispose();super.dispose();}
