 Future<void> publish()async{if(title.text.trim().isEmpty||desc.text.trim().isEmpty||price.text.trim().isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('عنوان، توضیحات و قیمت را کامل کنید.')));return;}final u=supabase.auth.currentUser;if(u==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ابتدا وارد حساب شوید.')));return;}final p=double.tryParse(price.text.replaceAll(RegExp(r'[^0-9.]'),''));if(p==null){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('قیمت را به صورت عدد وارد کنید.')));return;}if(category=='خودرو'&&(brand.text.trim().isEmpty||model.text.trim().isEmpty)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('برای خودرو برند و مدل را وارد کنید.')));return;}setState(()=>publishing=true);try{final row=await supabase.from('ads').insert({'seller_id':u.id,'title':title.text.trim(),'edescription':desc.text.trim(),'price':p,'city':city,'category':category,'subcategory':subcategory,'latitude':lat,'longitude':lon,'vehicle_brand':category=='خودرو'?brand.text.trim():null,'vehicle_model':category=='خودرو'?model.text.trim():null,'vehicle_year':category=='خودرو'?int.tryParse(year.text.trim()):null,'vehicle_mileage':category=='خودرو'?int.tryParse(mileage.text.trim()):null,'vehicle_color':category=='خودرو'?color.text.trim():null,'vehicle_transmission':category=='خودرو'?transmission:null,'vehicle_fuel':category=='خودرو'?fuel:null,'vehicle_body_condition':category=='خودرو'?body:null,'vehicle_exchange':category=='خودرو'?exchange:null}).select('idd').single();final id='${row['idd']}';String? imageError;try{await uploadImages(id,u.id);}catch(e){imageError='$e';}await widget.onPublished();if(mounted){await showDialog(context:context,builder:(ctx)=>AlertDialog(title:const Text('آگهی ثبت شد ✅'),content:Text(imageError==null?'آگهی با موفقیت ثبت شد.':'آگهی ثبت شد، اما بعضی عکس‌ها آپلود نشدند.'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('باشه'))]));if(mounted)Navigator.pop(context);}}on PostgrestException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('خطای ثبت آگهی: ${e.message}')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('خطا در ثبت آگهی: $e')));}finally{if(mounted)setState(()=>publishing=false);}}
