textField(desc,'توضیحات',maxLines:5),const SizedBox(height:12),textField(price,'قیمت (تومان)',keyboard:TextInputType.number),const SizedBox(height:12),Row(children:[Expanded(child:DropdownButtonFormField<String>(value:city,decoration:const InputDecoration(labelText:'شهر'),items:allIranCities().map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:publishing?null:(v){if(v!=null)setState(()=>city=v);}})),IconButton(onPressed:publishing?null:getLocation,icon:Icon(lat==null?Icons.my_location:Icons.location_on))]),if(lat!=null)Text('موقعیت ثبت شد: ${lat!.toStringAsFixed(5)}, ${lon!.toStringAsFixed(5)}'),const SizedBox(height:12),OutlinedButton.icon(onPressed:publishing||images.length>=10?null:pickImages,icon:const Icon(Icons.add_a_photo_outlined),label:Text('افزودن عکس (${images.length}/۱۰)')),if(images.isNotEmpty)SizedBox(height:105,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:images.length,separatorBuilder:(_,__)=>const SizedBox(width:8),itemBuilder:(context,i)=>FutureBuilder<Uint8List>(future:images[i].readAsBytes(),builder:(context,s)=>!s.hasData?const SizedBox(width:105,child:Center(child:CircularProgressIndicator())):Stack(children:[ClipRRect(borderRadius:BorderRadius.circular(12),child:Image.memory(s.data!,width:105,height:105,fit:BoxFit.cover)),Positioned(top:0,right:0,child:IconButton(onPressed:publishing?null:()=>setState(()=>images.removeAt(i)),icon:const Icon(Icons.cancel)))])))),const SizedBox(height:18),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:publishing?null:publish,icon:publishing?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.publish),label:Text(publishing?'در حال ثبت...':'ثبت آگهی')))])));}
 Widget _section(String t)=>Padding(padding:const EdgeInsets.only(bottom:10),child:Text(t,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold));
